exports.processTelemetry = (event, context) => {
  const file = event.bucket + '/' + event.name;

  return validateAndPublish(file)
    .then(() => console.log(`Processed: ${file}`))
    .catch(err => {
      console.error(`Error processing ${file}:`, err);
      throw err; // Triggers retry with exponential backoff
    });
